import json, importlib.util, sys
sys.path.insert(0, '.'); sys.path.insert(0, 'annotation')
import cut
spec = cut.cut_syntax_spec
opts, pos = spec[0]
print("syntax: %d option nodes, %d positional nodes" % (len(opts), len(pos)))
names = {o.flag for o in opts} | {a for o in opts for a in o.alias}
# every flag/option in the json must appear in the syntax spec and vice-versa
j = json.load(open('annotation/cut.json'))
jnames = set()
for e in j['flag']: jnames |= set([e] if isinstance(e,str) else e)
for e in j['option']: jnames |= set(x for x in e[:-1])
assert names == jnames, (names ^ jnames)
print("json/syntax names consistent:", sorted(names))
# simple PaSh-style parser from json
flags = {s for e in j['flag'] for s in ([e] if isinstance(e,str) else e)}
options = {s for e in j['option'] for s in e[:-1]}
def parse(argv):
    fo, ops, i = [], [], 0
    while i < len(argv):
        w = argv[i]
        if w in flags: fo.append(w)
        elif w in options: fo.append(w); i += 1
        elif w.startswith('--') and '=' in w and w.split('=')[0] in options: fo.append(w.split('=')[0])
        elif len(w) > 2 and w[0]=='-' and w[1] != '-' and w[:2] in options: fo.append(w[:2])  # -d: / -f1
        elif len(w) > 1 and w[0]=='-' and w[1] != '-' and all('-'+c in flags for c in w[1:]): fo += ['-'+c for c in w[1:]]
        else: ops = argv[i:]; break
        i += 1
    return fo, ops
from InputOutputInfoGeneratorCut import InputOutputInfoGeneratorCut as IO
from ParallelizabilityInfoGeneratorCut import ParallelizabilityInfoGeneratorCut as PAR
for argv in (["-d:","-f1","a","-","b"], ["--delimiter=:","--fields","2"], ["-sz","-d",":","-f","1","x"], ["-b","1-3","f"]):
    fo, ops = parse(argv)
    io = IO(fo, ops); io.generate_info()
    p = PAR(fo, ops); p.generate_info()
    print(argv, "->", fo, ops, "| io:", io.log, "| par:", p.log)
EOF
